-- Runtime of the chains generated by tests/gen.py.
--
-- The work directory comes from LJBT_WORKDIR (unix socket, box files,
-- oracle.jsonl, failures.jsonl).
local json = require('json')
local ffi = require('ffi')

local H = {}
local workdir = assert(os.getenv('LJBT_WORKDIR'), 'LJBT_WORKDIR is not set')

ffi.cdef([[
uint32_t box_space_id_by_name(const char *name, uint32_t len);
void qsort(void *base, size_t nmemb, size_t size,
           int (*compar)(const void *, const void *));
]])

-- Target names for the FFI target: NAMES[4000 + seq] has length 40 + seq
-- (the breakpoint condition and the probe's sequence number), NAMES[2000]
-- is the short name the non-final iterations of a hot loop use.
NAMES = {[2000] = 't'}

function H.setup(jit_on)
  box.cfg({
    listen = workdir .. '/s.sock', work_dir = workdir,
    memtx_dir = workdir, wal_mode = 'none',
    log = workdir .. '/tarantool.log',
    memtx_memory = 32 * 1024 * 1024,
  })
  if jit_on then jit.on() else jit.off() end
end

function H.name(seq)
  NAMES[4000 + seq] = string.rep('x', 40 + seq)
end

-- The last numeric for loop of fn runs in a trace (its FORL is a JFORL
-- now), or never will: the JIT is off or the loop is blacklisted (IFORL).
-- A loop gets its trace after as many iterations as its hot counter says,
-- one of 64 that all bytecode shares (lj_dispatch.h hotcount_get), and an
-- aborted trace anywhere may leave a penalty of 72 and more there
-- (lj_trace.c penalty_pc): no fixed count is surely enough.
local jutil = require('jit.util')
local vmdef = require('jit.vmdef')
function H.hot(fn)
  if not jit.status() then return true end
  local last
  local pc = 1
  while true do
    local ins = jutil.funcbc(fn, pc)
    if ins == nil then break end
    local op = bit.band(ins, 0xff)
    local name = vmdef.bcnames:sub(op * 6 + 1, op * 6 + 6):match('%S+')
    if name == 'FORL' or name == 'IFORL' or name == 'JFORL' then
      last = name
    end
    pc = pc + 1
  end
  return last == 'JFORL' or last == 'IFORL'
end

local function append(file, rec)
  local fh = assert(io.open(workdir .. '/' .. file, 'a'))
  fh:write(json.encode(rec) .. '\n')
  fh:close()
end

-- The snapshots of the trace of the last numeric for loop of fn (the D of
-- its JFORL), as LuaJIT's own jit.util.tracesnap gives them: for each, the
-- snapshot entries ((slot << 24) + flags + ref; SNAP_FRAME = 0x10000).
-- Written to snaps.jsonl, after the stop: what the snapshot lj-bt picks
-- holds, independently of lj-bt's reading of the snapshot map.
function H.snaps(seq, fn)
  local tr
  local pc = 1
  while true do
    local ins = jutil.funcbc(fn, pc)
    if ins == nil then break end
    local op = bit.band(ins, 0xff)
    local name = vmdef.bcnames:sub(op * 6 + 1, op * 6 + 6):match('%S+')
    if name == 'FORL' or name == 'IFORL' then tr = nil end
    if name == 'JFORL' then tr = bit.rshift(ins, 16) end
    pc = pc + 1
  end
  local snaps = {}
  if tr ~= nil then
    local sn = 0
    while true do
      local s = jutil.tracesnap(tr, sn)
      if s == nil then break end
      local ents = {}
      local k = 2
      while s[k] ~= nil and s[k] ~= s[#s] do
        ents[#ents + 1] = s[k]
        k = k + 1
      end
      snaps[#snaps + 1] = ents
      sn = sn + 1
    end
  end
  append('snaps.jsonl', {seq = seq, trace = tr, snaps = snaps})
end

-- The Lua chain as LuaJIT itself sees it (levels from the caller up to
-- the bottom of the current coroutine).
function H.oracle(seq)
  local levels = {}
  local level = 2
  while true do
    local info = debug.getinfo(level, 'Sl')
    if info == nil then break end
    table.insert(levels, {
      what = info.what, source = info.source, short_src = info.short_src,
      currentline = info.currentline, linedefined = info.linedefined,
    })
    level = level + 1
  end
  append('oracle.jsonl', {seq = seq, levels = levels})
end

function H.check(ok, err, seq)
  if not ok then
    append('failures.jsonl', {seq = seq, err = tostring(err)})
  end
end

return H
